-- Explicações por artigo — Lei de Tortura (Lei nº 9.455, de 1997). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constitui crime de tortura constranger alguém com emprego de violência ou grave ameaça, causando-lhe sofrimento físico ou mental, com o fim de obter informação, declaração ou confissão da vítima ou de terceira pessoa; para provocar ação ou omissão de natureza criminosa; ou em razão de discriminação racial ou religiosa; submeter alguém, sob sua guarda, poder ou autoridade, com emprego de violência ou grave ameaça, a intenso sofrimento físico ou mental, como forma de aplicar castigo pessoal ou medida de caráter preventivo; e submeter mulher, reiteradamente, a intenso sofrimento físico ou mental, no contexto de violência doméstica e familiar. Pena: reclusão de dois a oito anos. Na mesma pena incorre quem submete pessoa presa ou sujeita a medida de segurança a sofrimento físico ou mental por ato não previsto em lei ou não resultante de medida legal. Quem se omite, quando tinha o dever de evitar ou apurar, incorre em detenção de um a quatro anos. Se resulta lesão grave ou gravíssima, reclusão de quatro a dez anos; se resulta morte, de oito a dezesseis anos. A pena aumenta de um sexto até um terço se cometido por agente público, contra criança, gestante, pessoa com deficiência, adolescente ou maior de 60 anos, ou mediante sequestro. A condenação acarreta a perda do cargo e a interdição pelo dobro da pena. O crime é inafiançável e insuscetível de graça ou anistia, e o regime inicial é o fechado, salvo na omissão.', '["I: tortura-prova, tortura-crime e tortura-discriminação (constranger com violência ou grave ameaça).","II: tortura-castigo contra quem está sob guarda, poder ou autoridade.","III: tortura da mulher em violência doméstica, reiteradamente.","Pena: reclusão de 2 a 8 anos.","§1º: tortura de preso ou de quem cumpre medida de segurança.","§2º: omissão (detenção de 1 a 4 anos).","§3º: qualificadoras (lesão: quatro a dez anos; morte: oito a dezesseis anos).","§4º: aumento de 1/6 a 1/3.","§5º: perda do cargo e interdição pelo dobro da pena.","§6º e §7º: inafiançável, sem graça ou anistia; regime inicial fechado."]'::jsonb, '["ATUALIZAÇÃO: inciso III incluído pela Lei nº 15.410, de 2026 (tortura da mulher em violência doméstica).","Crime COMUM (qualquer pessoa pode praticar), com causa de aumento para agente público.","Equiparado a hediondo.","Perda do cargo: efeito da condenação, pelo dobro do prazo da pena."]'::jsonb, 'Policial que agride o preso para obter confissão pratica tortura, com aumento por ser agente público.', '["Assertiva que considera a tortura crime próprio de agente público erra: é crime comum, com aumento quando cometido por agente público."]'::jsonb, '[{"termo":"Tortura-prova","significado":"Tortura para obter informação, declaração ou confissão."}]'::jsonb, '["Lei dos Crimes Hediondos","Lei de Abuso de Autoridade"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'tortura' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O disposto na Lei aplica-se ainda quando o crime não tenha sido cometido em território nacional, sendo a vítima brasileira ou encontrando-se o agente em local sob jurisdição brasileira.', '["Aplica-se ao crime cometido fora do território nacional.","Quando a vítima for brasileira.","Ou quando o agente estiver em local sob jurisdição brasileira."]'::jsonb, '["Extraterritorialidade da lei brasileira."]'::jsonb, 'Tortura cometida no exterior contra um brasileiro pode ser punida pela lei brasileira.', '["Assertiva que restringe a lei ao crime cometido em território nacional erra."]'::jsonb, '[{"termo":"Extraterritorialidade","significado":"Aplicação da lei brasileira a fatos ocorridos no exterior."}]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
